(1070159, 129377, 12611, '<td valign="top">This is really pretty good- I think I like elements of it better than the original.</td>', 'This is really pretty good- I think I like elements of it better than the original.', '2004-12-20 07:47:35.000000', NULL, 1),
(1070160, 129270, 19952, '<td valign="top">This is a nicely faithful rendition of an outstanding photo. You did a great job with the colors and with lighting the glass without any reflections. Great job!</td>', 'This is a nicely faithful rendition of an outstanding photo. You did a great job with the colors and with lighting the glass without any reflections. Great job!', '2004-12-20 07:48:01.000000', NULL, 1),
