INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1070304, 128878, 3569, '<td valign="top">nice subject, a bit overexposed on right side</td>', 'nice subject, a bit overexposed on right side', '2004-12-20 09:23:22.000000', NULL, 1),
(1070310, 129462, 3569, '<td valign="top">great shot</td>', 'great shot', '2004-12-20 09:26:02.000000', NULL, 1),
(1070313, 128553, 6999, '<td valign="top">Without going back to the orignal, and whilst this is a fine copy of that image, I feel that the fade to white is too sudden here - whether I felt that about the orignal I don''t recall. Nicely done.</td>', 'Without going back to the orignal, and whilst this is a fine copy of that image, I feel that the fade to white is too sudden here - whether I felt that about the orignal I don''t recall. Nicely done.', '2004-12-20 09:27:37.000000', NULL, 1),
(1070314, 129021, 3569, '<td valign="top">a slight more contrast, a blue for you.</td>', 'a slight more contrast, a blue for you.', '2004-12-20 09:28:13.000000', NULL, 1),
(1070315, 128890, 3569, '<td valign="top">great contrasts</td>', 'great contrasts', '2004-12-20 09:29:01.000000', NULL, 1),
(1070317, 129170, 6999, '<td valign="top">Love the detail, the tonality, which is almost worthy of the master, I feel you haven''t quite achieved that strong sense of the compositional uses of shapes that JJ has.</td>', 'Love the detail, the tonality, which is almost worthy of the master, I feel you haven''t quite achieved that strong sense of the compositional uses of shapes that JJ has.', '2004-12-20 09:29:20.000000', NULL, 1),
(1070319, 129259, 3569, '<td valign="top">grains killing the shot</td>', 'grains killing the shot', '2004-12-20 09:29:44.000000', NULL, 1),
(1070321, 129398, 3569, '<td valign="top">a bit more contrast is needed to me</td>', 'a bit more contrast is needed to me', '2004-12-20 09:30:26.000000', NULL, 1),
(1070323, 129310, 6999, '<td valign="top">Nice idea. I think it needs the high contrast feel of the original, and the massive sense of detail in that shot to really make the impact. This ishowever plainly a tribute, and reasonably effective - it''s just that background colour which doesn''t have the stylish impact of the original.</td>', 'Nice idea. I think it needs the high contrast feel of the original, and the massive sense of detail in that shot to really make the impact. This ishowever plainly a tribute, and reasonably effective - it''s just that background colour which doesn''t have the stylish impact of the original.', '2004-12-20 09:31:11.000000', NULL, 1),
(1070328, 128849, 3569, '<td valign="top">great timing...</td>', 'great timing...', '2004-12-20 09:32:10.000000', NULL, 1),
(1070334, 128895, 6999, '<td valign="top">In amny senses this is a wild improvement on the original, which actually suffers from big technical problems. What you don''t have, for me, is the big bright punchy over-exposed feeling (good thing? bad thing? don''t know), and this to my eye suffers a bit for that - in a way it''s too realistic this, rather than having the disgned edge of the original. As a variation - well, the set-up itself is so very designed, that I''m not certain of the benefits of this approach.</td>', 'In amny senses this is a wild improvement on the original, which actually suffers from big technical problems. What you don''t have, for me, is the big bright punchy over-exposed feeling (good thing? bad thing? don''t know), and this to my eye suffers a bit for that - in a way it''s too realistic this, rather than having the disgned edge of the original. As a variation - well, the set-up itself is so very designed, that I''m not certain of the benefits of this approach.', '2004-12-20 09:34:35.000000', NULL, 1),
(1070336, 129377, 3569, '<td valign="top">excellent in all ways.</td>', 'excellent in all ways.', '2004-12-20 09:35:36.000000', NULL, 1),
(1070342, 128633, 6999, '<td valign="top">Nicely executed, though I''m surprised by your decision to shoot the book upside down - it''s good work, obviously, but just doesn''t quite do that extra thing for me, even with the broken thing.</td>', 'Nicely executed, though I''m surprised by your decision to shoot the book upside down - it''s good work, obviously, but just doesn''t quite do that extra thing for me, even with the broken thing.', '2004-12-20 09:38:16.000000', NULL, 1),
(1070349, 129377, 9939, '<td valign="top">Strictly comparing to the original shot, I prefer the lighting as it falls on the torso and the pattern of water droplets in the original. That said, this is an excellent shot on it''s own and it''s an excellent tribute. 8.</td>', 'Strictly comparing to the original shot, I prefer the lighting as it falls on the torso and the pattern of water droplets in the original. That said, this is an excellent shot on it''s own and it''s an excellent tribute. 8.', '2004-12-20 09:41:37.000000', NULL, 1),
(1070353, 128981, 6999, '<td valign="top">Pretty good, though there seems less fill light than the original. As a more or less straight copy I don''t find it that interesting (nor did I think that of the original, really), but such was the challenge you have to get decent points.</td>', 'Pretty good, though there seems less fill light than the original. As a more or less straight copy I don''t find it that interesting (nor did I think that of the original, really), but such was the challenge you have to get decent points.', '2004-12-20 09:43:39.000000', NULL, 1),
(1070355, 128945, 9939, '<td valign="top">Well done tribute- though it looks like the cover of your scanner could use a bit of cleaning :)</td>', 'Well done tribute- though it looks like the cover of your scanner could use a bit of cleaning :)', '2004-12-20 09:44:46.000000', NULL, 1),
(1070362, 129063, 9939, '<td valign="top">funny! Could use a shallower depth of field and more even lighting.</td>', 'funny! Could use a shallower depth of field and more even lighting.', '2004-12-20 09:47:31.000000', NULL, 1),
(1070366, 129280, 9939, '<td valign="top">Excellent way to tribute two different (yet related!) images, and very well shot. Nicely done!</td>', 'Excellent way to tribute two different (yet related!) images, and very well shot. Nicely done!', '2004-12-20 09:48:59.000000', NULL, 1),
(1070369, 129447, 6999, '<td valign="top">I''m not sure the additional matches does much for this - the impact of Kiwi''s shot, as so often with his work, is the absolutely perfect technicality, and simplicity, and sense of perseverence that you get from his photos. Not a bad image at all, by any means, but ... well, you''re tkaing on a master at this sort of thing, aren''t you?</td>', 'I''m not sure the additional matches does much for this - the impact of Kiwi''s shot, as so often with his work, is the absolutely perfect technicality, and simplicity, and sense of perseverence that you get from his photos. Not a bad image at all, by any means, but ... well, you''re tkaing on a master at this sort of thing, aren''t you?', '2004-12-20 09:51:29.000000', NULL, 1),
(1070371, 128796, 9939, '<td valign="top">funny, and a good tribute to two different shots. Unfortunately the Pride of London shot doesn''t stand up to the original, but this makes a great statement about that ;)</td>', 'funny, and a good tribute to two different shots. Unfortunately the Pride of London shot doesn''t stand up to the original, but this makes a great statement about that ;)', '2004-12-20 09:51:57.000000', NULL, 1),
(1070372, 128978, 9939, '<td valign="top">Exellent tribute!</td>', 'Exellent tribute!', '2004-12-20 09:53:35.000000', NULL, 1),
(1070374, 129478, 6999, '<td valign="top">Pretty good imitation, even, it appears to my eye, down to processing. Can''t quite see how you get the background colours and the plain white image in the water, and also your background image hasn''t the strength of organisation of the original.</td>', 'Pretty good imitation, even, it appears to my eye, down to processing. Can''t quite see how you get the background colours and the plain white image in the water, and also your background image hasn''t the strength of organisation of the original.', '2004-12-20 09:55:35.000000', NULL, 1),
(1070375, 129379, 9939, '<td valign="top">This has a snapshot quality to it that could definitely be improved upon- would love to see more even lighting, better detail in the eyes of both cats and a cleaner table surface! This shot does do a nice job of taking the original shot to the logical next step.</td>', 'This has a snapshot quality to it that could definitely be improved upon- would love to see more even lighting, better detail in the eyes of both cats and a cleaner table surface! This shot does do a nice job of taking the original shot to the logical next step.', '2004-12-20 09:56:52.000000', NULL, 1),
(1070378, 128981, 16148, '<td valign="top">Very nice!  Brought a smile to my face to see my only ribbon shot entered in this challenge.  I like the brown eggs and you didn''t over sharpen like I did.  Good luck in the challenge.</td>', 'Very nice!  Brought a smile to my face to see my only ribbon shot entered in this challenge.  I like the brown eggs and you didn''t over sharpen like I did.  Good luck in the challenge.', '2004-12-20 09:58:44.000000', NULL, 1),
(1070379, 129275, 9939, '<td valign="top">Excellent!</td>', 'Excellent!', '2004-12-20 10:01:20.000000', NULL, 1),
(1070380, 129185, 9939, '<td valign="top">Nice take and expansion on the original!</td>', 'Nice take and expansion on the original!', '2004-12-20 10:02:21.000000', NULL, 1),
(1070381, 129419, 6999, '<td valign="top">Ha! Oh man, I have absolutely no idea how to vote on this, at all. It''s a quite extraordinary feeling to see this, I can tell you - in a godd way, I assure you. I hope you''ll PM me about how you set it up. As to an assessment of it ...<br/> <br/>The one thing you''ve achieved here that is the kind of thing I was after in the orignal is the mad graduation of light across the curve of the spoon itself, just where the handle meets the bowl of it. Outside of that, it has a genuine simplicity that I like, but perhaps not the intensity of focus and closeness. The original is actually in a sense not lit at all - it is all reflections, rather than light falling directly on the subject - this seems directly lit, to me. Thankyou for it though, and I score you a 7.</td>', 'Ha! Oh man, I have absolutely no idea how to vote on this, at all. It''s a quite extraordinary feeling to see this, I can tell you - in a godd way, I assure you. I hope you''ll PM me about how you set it up. As to an assessment of it ... The one thing you''ve achieved here that is the kind of thing I was after in the orignal is the mad graduation of light across the curve of the spoon itself, just where the handle meets the bowl of it. Outside of that, it has a genuine simplicity that I like, but perhaps not the intensity of focus and closeness. The original is actually in a sense not lit at all - it is all reflections, rather than light falling directly on the subject - this seems directly lit, to me. Thankyou for it though, and I score you a 7.', '2004-12-20 10:02:51.000000', NULL, 1),
(1070382, 129474, 9939, '<td valign="top">Well done!</td>', 'Well done!', '2004-12-20 10:03:10.000000', NULL, 1),
(1070384, 129487, 9939, '<td valign="top">Doesn''t have the impact of the original. Nice idea though.</td>', 'Doesn''t have the impact of the original. Nice idea though.', '2004-12-20 10:05:52.000000', NULL, 1),
(1070395, 129377, 12448, '<td valign="top">You tribute is beautiful!  Nice job!   A 9</td>', 'You tribute is beautiful!  Nice job!   A 9', '2004-12-20 10:18:52.000000', NULL, 1),
(1070397, 128768, 12448, '<td valign="top">ROFLMAO!!!  9 for humor factor alone!`</td>', 'ROFLMAO!!!  9 for humor factor alone!`', '2004-12-20 10:19:11.000000', NULL, 1),
(1070398, 129182, 12448, '<td valign="top">Too funny!  It''s perfect!  10</td>', 'Too funny!  It''s perfect!  10', '2004-12-20 10:19:28.000000', NULL, 1),
(1070399, 129013, 12448, '<td valign="top">ROFLMAO!!!! I love it!!!!!!  A 10</td>', 'ROFLMAO!!!! I love it!!!!!!  A 10', '2004-12-20 10:19:44.000000', NULL, 1),
