INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1071215, 128849, 20779, '<td valign="top">I can''t believe that lightning struck twice and we got to have this treat for the eyes twice! Wonderful, lush, exciting capture.</td>', 'I can''t believe that lightning struck twice and we got to have this treat for the eyes twice! Wonderful, lush, exciting capture.', '2004-12-20 19:44:48.000000', NULL, 1),
(1071216, 129295, 6999, '<td valign="top">Oh man, if only the original was actually a ribbon winner. This is cool work though, especially in the rendition of post-processing. I''m torn between voting a one and a ten ...</td>', 'Oh man, if only the original was actually a ribbon winner. This is cool work though, especially in the rendition of post-processing. I''m torn between voting a one and a ten ...', '2004-12-20 19:45:10.000000', NULL, 1),
(1071217, 128661, 20779, '<td valign="top">Fascinating take on an image I have enjoyed looking at many times. Your new take is fabulous.</td>', 'Fascinating take on an image I have enjoyed looking at many times. Your new take is fabulous.', '2004-12-20 19:45:36.000000', NULL, 1),
(1071218, 129113, 20779, '<td valign="top">I don''t ususally score "toys" very high, but you have raised this to a whole new plane. Congrats on achieving excellence with your lighting, composition, tones, everything.</td>', 'I don''t ususally score "toys" very high, but you have raised this to a whole new plane. Congrats on achieving excellence with your lighting, composition, tones, everything.', '2004-12-20 19:47:03.000000', NULL, 1),
(1071221, 129495, 6999, '<td valign="top">Pretty good attempt - although the yellow colour cast was surely not there in the original shot? Some partial sections of the bases of the white pieces are visible, which plays against the illusion.</td>', 'Pretty good attempt - although the yellow colour cast was surely not there in the original shot? Some partial sections of the bases of the white pieces are visible, which plays against the illusion.', '2004-12-20 19:48:01.000000', NULL, 1),
(1071222, 128883, 20779, '<td valign="top">Wonderful expression of the original; captivating and unique just as it was, but instantly recognizable.</td>', 'Wonderful expression of the original; captivating and unique just as it was, but instantly recognizable.', '2004-12-20 19:48:04.000000', NULL, 1),
(1071223, 128890, 20779, '<td valign="top">You just nailed this so beautifully. Incredible lighting and detail.</td>', 'You just nailed this so beautifully. Incredible lighting and detail.', '2004-12-20 19:48:42.000000', NULL, 1),
(1071224, 128486, 20779, '<td valign="top">Stunning light and color. And this is one of those times that "centeredness" is just the right thing. Fascinating to just gaze here and let the eye move with the light.</td>', 'Stunning light and color. And this is one of those times that "centeredness" is just the right thing. Fascinating to just gaze here and let the eye move with the light.', '2004-12-20 19:50:01.000000', NULL, 1),
(1071227, 129280, 20779, '<td valign="top">Too funny!!!!!!!! And perfectly excecuted (no pun intended - lol).</td>', 'Too funny!!!!!!!! And perfectly excecuted (no pun intended - lol).', '2004-12-20 19:50:47.000000', NULL, 1),
(1071228, 128878, 20779, '<td valign="top">Beautiful, intriguing tribute. Well done!</td>', 'Beautiful, intriguing tribute. Well done!', '2004-12-20 19:51:17.000000', NULL, 1),
(1071229, 129477, 20779, '<td valign="top">So clever, and so exquisitely done.</td>', 'So clever, and so exquisitely done.', '2004-12-20 19:51:54.000000', NULL, 1),
(1071230, 129362, 16739, '<td valign="top">very clear , great lighting  7</td>', 'very clear , great lighting  7', '2004-12-20 19:52:26.000000', NULL, 1),
(1071231, 129450, 16739, '<td valign="top">great shot   7</td>', 'great shot   7', '2004-12-20 19:52:49.000000', NULL, 1),
(1071232, 129270, 16739, '<td valign="top">very good , great lighting  7</td>', 'very good , great lighting  7', '2004-12-20 19:53:16.000000', NULL, 1),
(1071233, 129158, 6999, '<td valign="top">Really excellent use of this light, and great detailing in the face. Strong crop. Hasn''t quite the wild intensity of the original - though I can see how that might be considered an improvement, I think that shot had more emotion than this. Not to be doing down the sense of calm and a certain solemnity here.</td>', 'Really excellent use of this light, and great detailing in the face. Strong crop. Hasn''t quite the wild intensity of the original - though I can see how that might be considered an improvement, I think that shot had more emotion than this. Not to be doing down the sense of calm and a certain solemnity here.', '2004-12-20 19:53:32.000000', NULL, 1),
(1071234, 129270, 20779, '<td valign="top">This just sings with light - it knocked me out all over again - even better this time around maybe. Great tribute to both photographers or yourself - if this was yours originally!</td>', 'This just sings with light - it knocked me out all over again - even better this time around maybe. Great tribute to both photographers or yourself - if this was yours originally!', '2004-12-20 19:53:36.000000', NULL, 1),
(1071235, 128336, 16739, '<td valign="top">very good  7</td>', 'very good  7', '2004-12-20 19:53:39.000000', NULL, 1),
(1071238, 128849, 16739, '<td valign="top">the orignal shot is one of my favorites , you did it justice 8</td>', 'the orignal shot is one of my favorites , you did it justice 8', '2004-12-20 19:54:42.000000', NULL, 1),
(1071239, 128553, 16739, '<td valign="top">very nice  7</td>', 'very nice  7', '2004-12-20 19:55:07.000000', NULL, 1),
(1071240, 129492, 6999, '<td valign="top">Not a bad image, and I like the way the refraction has become the main focus of the shot - you add to the idea of the original by taking elements away, which for me is strong.</td>', 'Not a bad image, and I like the way the refraction has become the main focus of the shot - you add to the idea of the original by taking elements away, which for me is strong.', '2004-12-20 19:55:31.000000', NULL, 1),
(1071241, 129474, 20779, '<td valign="top">Very clever take and well done.</td>', 'Very clever take and well done.', '2004-12-20 19:56:10.000000', NULL, 1),
(1071242, 128954, 16739, '<td valign="top">I didnt get at first , you know what happen to the 2 , great job , very sharp  6</td>', 'I didnt get at first , you know what happen to the 2 , great job , very sharp  6', '2004-12-20 19:56:35.000000', NULL, 1),
(1071243, 129296, 20779, '<td valign="top">I love your choice of tributes - the original and yours!</td>', 'I love your choice of tributes - the original and yours!', '2004-12-20 19:56:58.000000', NULL, 1),
(1071247, 129207, 16739, '<td valign="top">good job , now you know hard it is  6</td>', 'good job , now you know hard it is  6', '2004-12-20 19:58:11.000000', NULL, 1),
