(1073007, 129398, 29168, '<td valign="top">Gorgeous! Looking forward to finding out where you found this critter. Good photography too. 9.</td>', 'Gorgeous! Looking forward to finding out where you found this critter. Good photography too. 9.', '2004-12-21 23:51:39.000000', NULL, 1),
(1073009, 129092, 29168, '<td valign="top">Humorous paody. I sold both my guitars and am left with just the woman now. I feel I may have made a kistake at times! :) A few blemishes could have been removed given advanced editing rules. 8.</td>', 'Humorous paody. I sold both my guitars and am left with just the woman now. I feel I may have made a kistake at times! :) A few blemishes could have been removed given advanced editing rules. 8.', '2004-12-21 23:53:55.000000', NULL, 1),
(1073029, 129459, 29168, '<td valign="top">That''s really cool. Nice twist :) 8.</td>', 'That''s really cool. Nice twist :) 8.', '2004-12-22 00:04:43.000000', NULL, 1),
(1073032, 129224, 29168, '<td valign="top">Not an easy shot this. In this case I think maybe not enough lighting</td>', 'Not an easy shot this. In this case I think maybe not enough lighting', '2004-12-22 00:06:34.000000', NULL, 1),
(1073034, 128773, 29168, '<td valign="top">AAaaaarrrrrggggh!!! (I love it, really. Just don''t tell the others! Mmmmkay?)  9.</td>', 'AAaaaarrrrrggggh!!! (I love it, really. Just don''t tell the others! Mmmmkay?)  9.', '2004-12-22 00:07:47.000000', NULL, 1),
