(1073265, 128862, 18367, '<td valign="top">I loved this photo.  Laughed till I cried when I saw it.  I am ever so curious as to how you managed to get your cat to lick his "chops" like that.  Perhaps the use of honey or other similar product.  Congratulations on a job well done.  Top of the scale for me.</td>', 'I loved this photo.  Laughed till I cried when I saw it.  I am ever so curious as to how you managed to get your cat to lick his "chops" like that.  Perhaps the use of honey or other similar product.  Congratulations on a job well done.  Top of the scale for me.', '2004-12-22 01:51:00.000000', NULL, 1),
(1073291, 128773, 29132, '<td valign="top">Very funny -- a strangely statuesque tribute to the original. A 10.</td>', 'Very funny -- a strangely statuesque tribute to the original. A 10.', '2004-12-22 02:08:25.000000', NULL, 1),
(1073293, 128981, 29132, '<td valign="top">Gorgeous color and shadows -- a 10!</td>', 'Gorgeous color and shadows -- a 10!', '2004-12-22 02:08:54.000000', NULL, 1),
