INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1073351, 128964, 16648, '<td valign="top">Seems underexposed to me..the snow is a dark dirty gray not a moonlit blue.</td>', 'Seems underexposed to me..the snow is a dark dirty gray not a moonlit blue.', '2004-12-22 02:50:42.000000', NULL, 1),
(1073354, 129259, 16648, '<td valign="top">Cool shot. Interested to know how you did it. Seems grainy though - the blue in the upper right and the green lower left.</td>', 'Cool shot. Interested to know how you did it. Seems grainy though - the blue in the upper right and the green lower left.', '2004-12-22 02:51:41.000000', NULL, 1),
(1073356, 129452, 16648, '<td valign="top">Good copy. The mouth on the original was better, more sensual. Also, the chin is blowing out on the one side. Perhaps the white background was too bright.</td>', 'Good copy. The mouth on the original was better, more sensual. Also, the chin is blowing out on the one side. Perhaps the white background was too bright.', '2004-12-22 02:53:54.000000', NULL, 1),
(1073358, 129279, 16648, '<td valign="top">Neat pic, but it does not meet the challenge - this looks nothing like the ribboners in that challenge, and the title does not tie it to one of them.</td>', 'Neat pic, but it does not meet the challenge - this looks nothing like the ribboners in that challenge, and the title does not tie it to one of them.', '2004-12-22 02:55:45.000000', NULL, 1),
(1073359, 129014, 16648, '<td valign="top">I had already submitted when i saw this old winner..i have the same camera so i shold have treid it instead of trying to compete with a dLSR!</td>', 'I had already submitted when i saw this old winner..i have the same camera so i shold have treid it instead of trying to compete with a dLSR!', '2004-12-22 02:58:41.000000', NULL, 1),
(1073361, 129021, 16648, '<td valign="top">Nice,but not pin sharp. The feathers are not that sharp, particularly on the wing on the left and on the top of the head. Perhaps some USM?.</td>', 'Nice,but not pin sharp. The feathers are not that sharp, particularly on the wing on the left and on the top of the head. Perhaps some USM?.', '2004-12-22 03:00:16.000000', NULL, 1),
(1073362, 129398, 16648, '<td valign="top">Looks a tad hazy - try USM with these settings - 35%, 60 radius, and 1.</td>', 'Looks a tad hazy - try USM with these settings - 35%, 60 radius, and 1.', '2004-12-22 03:01:19.000000', NULL, 1),
(1073366, 128573, 16648, '<td valign="top">I like how the white pencil blends into the white paper/background. if the blue would do that too...</td>', 'I like how the white pencil blends into the white paper/background. if the blue would do that too...', '2004-12-22 03:02:09.000000', NULL, 1),
(1073467, 128633, 30429, '<td valign="top">at least you had details about doing something like this. anyhow, i like it very much :)</td>', 'at least you had details about doing something like this. anyhow, i like it very much :)', '2004-12-22 05:33:48.000000', NULL, 1),
(1073528, 129013, 29132, '<td valign="top">Ouch!!! -- Painfully funny :)</td>', 'Ouch!!! -- Painfully funny :)', '2004-12-22 07:31:14.000000', NULL, 1),
(1073530, 129377, 29132, '<td valign="top">Great lighting on an all-around excellent photo -- a ten!</td>', 'Great lighting on an all-around excellent photo -- a ten!', '2004-12-22 07:32:52.000000', NULL, 1),
(1073532, 128456, 29132, '<td valign="top">Nice recreation of the Escher effect -- a 10 because it kept me captivated.</td>', 'Nice recreation of the Escher effect -- a 10 because it kept me captivated.', '2004-12-22 07:37:35.000000', NULL, 1),
(1073604, 129317, 14603, '<td valign="top">Firstly,thanks for the mention :)<br/>Good to see that you put your own spin on this..the eye is nicely drawn to the door by the use of the steps and handrail in the composition.<br/>What may hurt you is that the desat is harder to notice in these type of buildings which tend to be a natural grey colour anyway.<br/>A way round this may have been to take the colour out of the door but leaving it in the glass reflections.<br/>Hopefully, that won`t matter too much...good luck.<br/></td>', 'Firstly,thanks for the mention :)Good to see that you put your own spin on this..the eye is nicely drawn to the door by the use of the steps and handrail in the composition.What may hurt you is that the desat is harder to notice in these type of buildings which tend to be a natural grey colour anyway.A way round this may have been to take the colour out of the door but leaving it in the glass reflections.Hopefully, that won`t matter too much...good luck.', '2004-12-22 08:37:56.000000', NULL, 1),
(1073605, 129000, 11738, '<td valign="top">You really should have indicated what image, member or challenge you were paying tribute to in your title.  Most of us don''t have the time to screen through all the winners to find out which image you''re referring to, if any.</td>', 'You really should have indicated what image, member or challenge you were paying tribute to in your title.  Most of us don''t have the time to screen through all the winners to find out which image you''re referring to, if any.', '2004-12-22 08:38:47.000000', NULL, 1),
(1073621, 129214, 11738, '<td valign="top">One word: excellent!</td>', 'One word: excellent!', '2004-12-22 08:44:23.000000', NULL, 1),
(1073624, 129208, 11738, '<td valign="top">Could have used a bit more light on that flower.</td>', 'Could have used a bit more light on that flower.', '2004-12-22 08:44:47.000000', NULL, 1),
