(1074913, 128849, 23458, '<td valign="top">hehe - the background is a little too busy for this to have the same impact as the original. But definately a terrific capture here. 8.</td>', 'hehe - the background is a little too busy for this to have the same impact as the original. But definately a terrific capture here. 8.', '2004-12-22 23:55:30.000000', NULL, 1),
(1074915, 128796, 23458, '<td valign="top">Ooh ... hate to be a wet rag - but I hope you either are imagineer or got his permission for this. Tenuous on copyright grounds, though an amusing and interesting take here. 7.</td>', 'Ooh ... hate to be a wet rag - but I hope you either are imagineer or got his permission for this. Tenuous on copyright grounds, though an amusing and interesting take here. 7.', '2004-12-22 23:56:48.000000', NULL, 1),
